{"Channel": {"name": "bug-georgegarcia-SummarizeForce", "channelID": "ch-force-f638bf"}, "Message": {"User": {"userId": "eid_95f6d01c", "timestamp": "2027-04-11T09:59:00", "text": "Hi team, several customers are reporting issues with SummarizeForce that we need to address ASAP. Let's go through them one by one. 🚀", "utterranceID": "20270411-0-2367a"}, "Reactions": []}, "ThreadReplies": [], "id": "20270411-0-2367a"}
