{"Channel": {"name": "bug-emmamiller-SummarizeForce", "channelID": "ch-force-4ea428"}, "Message": {"User": {"userId": "eid_13cb0e90", "timestamp": "2027-04-28T12:13:00", "text": "Sure thing! I'll check the API configurations and see how we can adjust the rate limits to ensure real-time updates. 🚀", "utterranceID": "20270428-4-e9cb3"}, "Reactions": []}, "ThreadReplies": [], "id": "20270428-4-e9cb3"}
