{"Channel": {"name": "bug-davidgarcia-SummarizeForce", "channelID": "ch-force-9223c9"}, "Message": {"User": {"userId": "eid_e3c15ff5", "timestamp": "2027-05-02T00:45:00", "text": "Hi team, I looked into the reported issue about 'Incorrect User Permissions Allow Unauthorized Access'.", "utterranceID": "20270501-0-28598"}, "Reactions": []}, "ThreadReplies": [], "id": "20270501-0-28598"}
