{"Channel": {"name": "planning-ATF_AIX", "channelID": "ch-f_aix-3a5e7c"}, "Message": {"User": {"userId": "eid_b67edbb4", "timestamp": "2026-06-24T21:34:00", "text": "Regarding integration issues, we might need to expand our API support. Including more data formats and protocols could enhance compatibility with third-party data sources. This should be highlighted in the integration section.", "utterranceID": "20260624-5-e78d9"}, "Reactions": []}, "ThreadReplies": [], "id": "20260624-5-e78d9"}
